import{_ as n,o as r,c as a,a3 as t}from"./chunks/framework.z_KJ15Ep.js";const i="/bilder/unterricht-kataloge/kataloge-allgemein-aufklappmenue.png",l="/bilder/unterricht-kataloge/kataloge-allgemein-neuer-datensatz.png",o="/bilder/unterricht-kataloge/kataloge-allgemein-suchen.png",g="/bilder/unterricht-kataloge/kataloge-allgemein-sortierung-sichtbar.png",b=JSON.parse('{"title":"Katalogeinträge anlegen, sortieren und anzeigen","description":"","frontmatter":{"title":"Katalogeinträge anlegen, sortieren und anzeigen","source_pageid":259,"source_revision":5416},"headers":[],"relativePath":"schild3/unterricht-kataloge/allgemeine-kataloge-kataloge.md","filePath":"schild3/unterricht-kataloge/allgemeine-kataloge-kataloge.md"}'),s={name:"schild3/unterricht-kataloge/allgemeine-kataloge-kataloge.md"};function d(h,e,u,c,p,k){return r(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="katalogeintrage-anlegen-sortieren-und-anzeigen" tabindex="-1">Katalogeinträge anlegen, sortieren und anzeigen <a class="header-anchor" href="#katalogeintrage-anlegen-sortieren-und-anzeigen" aria-label="Permalink to &quot;Katalogeinträge anlegen, sortieren und anzeigen&quot;">​</a></h1><p>Lernen Sie die gemeinsamen Funktionen der Kataloge kennen: Einträge hinzufügen oder löschen, suchen, sortieren, ausblenden und nach Excel exportieren.</p><p><a href="/bilder/unterricht-kataloge/kataloge-allgemein-aufklappmenue.png"><img src="'+i+'" alt="Ein Dropdown-Menü, das über einen Katalog gesteuert wird. Hier werden Konfessionen angezeigt." loading="lazy"></a></p><p><em>Ein Dropdown-Menü, das über einen Katalog gesteuert wird. Hier werden Konfessionen angezeigt.</em></p><p>In SchILD-NRW gibt es an vielen Stellen Felder, deren Werte über Aufklappmenüs oder Dropdown-Menüs ausgewählt werden.</p><p>Welche Auswahloptionen hier jeweils angezeigt werden und in welcher Reihenfolge sie stehen, kann im Karteireiter <em>Kataloge</em> eingestellt werden.</p><h2 id="gemeinsamkeiten-aller-kataloge" tabindex="-1">Gemeinsamkeiten aller Kataloge <a class="header-anchor" href="#gemeinsamkeiten-aller-kataloge" aria-label="Permalink to &quot;Gemeinsamkeiten aller Kataloge&quot;">​</a></h2><h3 id="einfugen-und-loschen-von-eintragen" tabindex="-1">Einfügen und Löschen von Einträgen <a class="header-anchor" href="#einfugen-und-loschen-von-eintragen" aria-label="Permalink to &quot;Einfügen und Löschen von Einträgen&quot;">​</a></h3><p><a href="/bilder/unterricht-kataloge/kataloge-allgemein-neuer-datensatz.png"><img src="'+l+'" alt="Die Werkzeugleiste zum Einfügen, Löschen oder für andere Aktionen." loading="lazy"></a></p><p><em>Die Werkzeugleiste zum Einfügen, Löschen oder für andere Aktionen.</em></p><p>Durch einen Klick auf das <strong>+</strong> kann ein neuer Eintrag vor der aktuell ausgewählten Position eingefügt werden.</p><p>Der Eintrag wird durch einen Klick auf den Haken <strong>✓</strong> oder durch den Klick in eine andere Zeile der Tabelle übernommen.</p><p>Durch einen Klick auf das <strong>-</strong> kann der aktuell ausgewählte Datensatz, in einem Katalog ist das eine <em>Tabellenzeile</em>, gelöscht werden.</p><h3 id="suchen" tabindex="-1">Suchen <a class="header-anchor" href="#suchen" aria-label="Permalink to &quot;Suchen&quot;">​</a></h3><p><a href="/bilder/unterricht-kataloge/kataloge-allgemein-suchen.png"><img src="'+o+'" alt="Größere Kataloge können ein Suchfeld anbieten." loading="lazy"></a></p><p><em>Größere Kataloge können ein Suchfeld anbieten.</em></p><p>Bei Katalogen mit sehr vielen Einträgen kann es hilfreich sein die Suchfunktion zu benutzen.</p><p>Hierzu wird der Suchbegriff in das Feld über der Tabelle eingegeben und entweder mit der Return-Taste oder durch einen Klick auf das Filtersymbol am rechten Ende des Eingabefeldes bestätigt.</p><p>Zur Aufhebung des Suchfilters kann dann das <strong>X</strong> rechts neben dem Suchfeld angeklickt werden.</p><h3 id="sortierung" tabindex="-1">Sortierung <a class="header-anchor" href="#sortierung" aria-label="Permalink to &quot;Sortierung&quot;">​</a></h3><p><a href="/bilder/unterricht-kataloge/kataloge-allgemein-sortierung-sichtbar.png"><img src="'+g+'" alt="Festlegen der Sortierung und der Sichtbarkeit eines Katalogeintrags im Dropdown-Menü. Mitunterst steht ein Excel-Export zur Verfügung." loading="lazy"></a></p><p><em>Festlegen der Sortierung und der Sichtbarkeit eines Katalogeintrags im Dropdown-Menü. Mitunterst steht ein Excel-Export zur Verfügung.</em></p><p>Je nach Katalog stehen eine Sortierung nach vorgegebenen Spalten und eine benutzerdefinierte Reihenfolge zur Verfügung. <strong>Lernplattformen</strong> bieten keine benutzerdefinierte Sortierung. Für Kataloge mit dieser Funktion gehen Sie so vor:</p><p>Hierzu wird die Sortierung auf <strong>Benutzerdefiniert</strong> gestellt, so dass links neben der Tabelle mit den Katalogeinträgen rote Pfeile aktiv werden.</p><p>Nun kann die Reihenfolge der Tabelleneinträge verändert werden</p><ul><li>indem der zu verschiebende Eintrag angeklickt und anschließend mit Hilfe der Pfeile nach oben oder nach unten verschoben wird. Ein einfacher Pfeil verschiebt den Eintrag um eine Stelle, ein doppelter Pfeil um zehn. Erreichen Sie mit einer Verschiebungsaktion das Ende der Liste, fragt SchILD-NRW, ob die Daten &quot;reorganisiert&quot; werden sollen. Diese Frage kann bejaht werden, hier werden dann die Indizes neu geschrieben.</li><li>indem in der Spalte <strong>Sortierung</strong> Zahlen eingetragen werden, die der gewünschten Reihenfolge entsprechen. Durch einen Klick auf <strong>Daten aktualisieren</strong> wird die Tabelle der neuen Reihenfolge entsprechend sortiert.</li></ul><h3 id="sichtbarkeit" tabindex="-1">Sichtbarkeit <a class="header-anchor" href="#sichtbarkeit" aria-label="Permalink to &quot;Sichtbarkeit&quot;">​</a></h3><p>Durch Abwahl des Häkchens in der Spalte <strong>Sichtbar</strong> können Einträge aus den Aufklappmenüs entfernt werden, die aktuell nicht benötigt werden aber nicht endgültig gelöscht werden sollen.</p><p>Ausblenden ist für nicht mehr benötigte Einträge sinnvoll, die für frühere Datensätze erhalten bleiben sollen, etwa ausgeschiedene Lehrkräfte. Diese Funktion gibt es nicht in jeder Tabelle: <strong>Klassen werden in SchILD-NRW 3 abschnittsbezogen geführt</strong>. Wählen Sie bei Klassen den benötigten Lernabschnitt.</p><h3 id="excel-export" tabindex="-1">Excel-Export <a class="header-anchor" href="#excel-export" aria-label="Permalink to &quot;Excel-Export&quot;">​</a></h3><p>Die Kataloge können im Excel-Format exportiert werden, um außerhalb von SchILD-NRW verwendet zu werden.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Allgemeine_Kataloge_(Kataloge)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5416.</p>',33)])])}const f=n(s,[["render",d]]);export{b as __pageData,f as default};
